fields.html:
{% if doc.items %}
{% set has_cgst = namespace(val=False) %}
{% set has_sgst = namespace(val=False) %}
{% set has_igst = namespace(val=False) %}
{% for item in doc.items %}
{% if item.cgst_amount %}{% set has_cgst.val = True %}{% endif %}
{% if item.sgst_amount %}{% set has_sgst.val = True %}{% endif %}
{% if item.igst_amount %}{% set has_igst.val = True %}{% endif %}
{% endfor %}

{% set groups = doc.items|groupby('gst_hsn_code') %}
{% if groups|length > 0 %}
<div class="hsn-tax-table">
    <table class="table hsn-table">
        <thead>
            <tr>
                <th class="hsn-col">HSN/SAC</th>
                <th class="taxable-col">Taxable Amount</th>
                {% if has_igst.val %}
                <th>IGST Rate</th>
                <th>IGST Amount</th>
                {% endif %}
                {% if has_cgst.val %}
                <th>CGST Rate</th>
                <th>CGST Amount</th>
                {% endif %}
                {% if has_sgst.val %}
                <th>SGST Rate</th>
                <th>SGST Amount</th>
                {% endif %}
                <th class="total-tax-col">Total Tax</th>
                <th class="total-amount-col">Total Amount</th>
            </tr>
        </thead>
        <tbody>
            {% for group in groups %}
            {% set ns = namespace(taxable=0, cgst_amt=0, sgst_amt=0, igst_amt=0, cgst_rate=0, sgst_rate=0, igst_rate=0) %}
            {% for item in group.list %}
            {% set ns.taxable = ns.taxable + item.taxable_value %}
            {% set ns.cgst_amt = ns.cgst_amt + (item.cgst_amount or 0) %}
            {% set ns.sgst_amt = ns.sgst_amt + (item.sgst_amount or 0) %}
            {% set ns.igst_amt = ns.igst_amt + (item.igst_amount or 0) %}
            {% set ns.cgst_rate = item.cgst_rate or 0 %}
            {% set ns.sgst_rate = item.sgst_rate or 0 %}
            {% set ns.igst_rate = item.igst_rate or 0 %}
            {% endfor %}
            {% set total_tax = ns.cgst_amt + ns.sgst_amt + ns.igst_amt %}
            <tr>
                <td class="hsn-col">{{ group.grouper or 'N/A' }}</td>
                <td class="taxable-col">{{ frappe.utils.fmt_money(ns.taxable, currency=doc.company_currency) }}</td>
                {% if has_igst.val %}
                <td>{{ ns.igst_rate }}%</td>
                <td>{{ frappe.utils.fmt_money(ns.igst_amt, currency=doc.company_currency) }}</td>
                {% endif %}
                {% if has_cgst.val %}
                <td>{{ ns.cgst_rate }}%</td>
                <td>{{ frappe.utils.fmt_money(ns.cgst_amt, currency=doc.company_currency) }}</td>
                {% endif %}
                {% if has_sgst.val %}
                <td>{{ ns.sgst_rate }}%</td>
                <td>{{ frappe.utils.fmt_money(ns.sgst_amt, currency=doc.company_currency) }}</td>
                {% endif %}
                <td class="total-tax-col">{{ frappe.utils.fmt_money(total_tax, currency=doc.company_currency) }}</td>
                <td class="total-amount-col">{{ frappe.utils.fmt_money(ns.taxable + total_tax, currency=doc.company_currency) }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>
</div>
{% endif %}
{% endif %}

{% if doc.taxes %}
<div class="tax-summary">
    {% for i in doc.taxes %}
    <div class="tax-row">
        <span class="tax-label">{{ i.account_head }}</span>
        <span class="tax-amount">{{ i.get_formatted('tax_amount') }}</span>
    </div>
    {% endfor %}
</div>
{% endif %}
{% if doc.in_words %}
<div class="in-words">
    <span class="iw-label">In Words:</span>
    <span class="iw-value">{{ doc.in_words }}</span>
</div>
{% endif %}
